{"content": "import fcntl, struct, os, sys, glob, re

QUERYCAP   = 0x80685600   # _IOR ('V',  0, 104) v4l2_capability
ENUM_FMT   = 0xC0405602   # _IOWR('V',  2,  64) v4l2_fmtdesc
ENUM_SIZES = 0xC038564A   # _IOWR('V', 74,  56) v4l2_frmsizeenum
ENUM_IVALS = 0xC03C564B   # _IOWR('V', 75,  60) v4l2_frmivalenum

CAP_VIDEO_CAPTURE = 0x00000001
BUF_TYPE_CAPTURE  = 1
TYPE_DISCRETE     = 1

# V4L2 fourcc -> ffmpeg input_format 名字（mpv/ffmpeg 的 input_format 用的是后者）
FFMPEG_NAME = {
    'MJPG': 'mjpeg',   'JPEG': 'mjpeg',
    'YUYV': 'yuyv422', 'UYVY': 'uyvy422',
    'NV12': 'nv12',    'NV21': 'nv21',
    'YU12': 'yuv420p', 'YV12': 'yuv420p',
    '422P': 'yuv422p', 'YU16': 'yuv420p16le',
    'GREY': 'gray',    'RGB3': 'rgb24', 'BGR3': 'bgr24',
    'H264': 'h264',    'HEVC': 'hevc',
}


def fourcc(v):
    return ''.join(chr((v >> (8 * i)) & 0xff) for i in range(4))


def card_name(fd):
    buf = bytearray(104)
    fcntl.ioctl(fd, QUERYCAP, buf, True)
    driver = bytes(buf[0:16]).split(b'\0')[0].decode(errors='replace')
    card = bytes(buf[16:48]).split(b'\0')[0].decode(errors='replace')
    caps = struct.unpack_from('<I', buf, 84)[0]      # capabilities
    dcaps = struct.unpack_from('<I', buf, 88)[0]     # device_caps
    return driver, card, (dcaps or caps)


def is_capture(path):
    try:
        fd = os.open(path, os.O_RDWR | os.O_NONBLOCK)
    except OSError:
        return None
    try:
        driver, card, caps = card_name(fd)
    except OSError:
        os.close(fd)
        return None
    os.close(fd)
    if not (caps & CAP_VIDEO_CAPTURE):
        return None
    return driver, card


def enum_formats(fd):
    out, i = [], 0
    while True:
        buf = bytearray(64)
        struct.pack_into('<III', buf, 0, i, BUF_TYPE_CAPTURE, 0)
        try:
            fcntl.ioctl(fd, ENUM_FMT, buf, True)
        except OSError:
            break
        desc = bytes(buf[8:40]).split(b'\0')[0].decode(errors='replace')
        pix = struct.unpack_from('<I', buf, 40)[0]
        out.append((fourcc(pix), desc))
        i += 1
    return out


def enum_sizes(fd, pix):
    """返回 [(w, h), ...]，按 v4l2 枚举顺序。"""
    out, i = [], 0
    while True:
        buf = bytearray(56)
        struct.pack_into('<III', buf, 0, i, pix, TYPE_DISCRETE)
        try:
            fcntl.ioctl(fd, ENUM_SIZES, buf, True)
        except OSError:
            break
        t = struct.unpack_from('<I', buf, 8)[0]
        if t != TYPE_DISCRETE:
            break
        w, h = struct.unpack_from('<II', buf, 12)
        out.append((w, h))
        i += 1
    return out


def enum_fps(fd, pix, w, h):
    out, i = [], 0
    while True:
        buf = bytearray(60)
        struct.pack_into('<IIIII', buf, 0, i, pix, w, h, TYPE_DISCRETE)
        try:
            fcntl.ioctl(fd, ENUM_IVALS, buf, True)
        except OSError:
            break
        t = struct.unpack_from('<I', buf, 16)[0]
        if t != TYPE_DISCRETE:
            break
        num, den = struct.unpack_from('<II', buf, 20)
        if num:
            out.append(den / num)
        i += 1
    return out


def fmt_fps(f):
    return str(int(f)) if abs(f - round(f)) < 1e-6 else ('%.2f' % f).rstrip('0')


def cmd_devices():
    paths = sorted(glob.glob('/dev/video*'),
                   key=lambda p: int(re.sub(r'\D', '', p) or 0))
    for p in paths:
        r = is_capture(p)
        if r:
            print('DEV\t%s\t%s\t%s' % (p, r[1], r[0]))


def cmd_info(path):
    fd = os.open(path, os.O_RDWR | os.O_NONBLOCK)
    for pix, desc in enum_formats(fd):
        name = FFMPEG_NAME.get(pix, pix.lower())
        print('FMT\t%s\t%s\t%s' % (pix, name, desc))
        for w, h in enum_sizes(fd, struct.unpack('<I', pix.encode())[0]):
            print('SIZE\t%s\t%d\t%d' % (pix, w, h))
            for f in enum_fps(fd, struct.unpack('<I', pix.encode())[0], w, h):
                print('FPS\t%s\t%d\t%d\t%s' % (pix, w, h, fmt_fps(f)))
    os.close(fd)


if __name__ == '__main__':
    if len(sys.argv) >= 2 and sys.argv[1] == 'devices':
        cmd_devices()
    elif len(sys.argv) >= 3 and sys.argv[1] == 'info':
        cmd_info(sys.argv[2])
    else:
        sys.stderr.write('usage: %s devices | info <device>\n' % sys.argv[0])
        sys.exit(2)
