{"content": "#!/usr/bin/env python3
"""cam-focus — 锁住 / 放开 USB 摄像头的自动对焦。

走 UVC 的相机终端控件（纯 V4L2 ioctl，不需要 v4l-utils，也不需要装任何东西）。
对焦是设备侧设置：设置完正在跑的 ffplay / mpv 立刻生效，不用重启；
但拔插 USB 或重启后就没了。

用法:
  cam-focus                   列出全部控件及当前值（默认 /dev/video0）
  cam-focus lock              关闭连续自动对焦：镜头就地冻结在当前焦点
  cam-focus lock 120          关闭自动对焦并把焦点设到 120（范围先看 list）
  cam-focus auto              恢复连续自动对焦
  cam-focus -d /dev/video2 …  换设备

注意 顺序: 必须先关自动对焦再设焦点值。自动对焦开着时「Focus, Absolute」
是 inactive 的，设了不生效。值的方向（大=远还是近）各机型固件不同，
自己从当前值附近试。
"""

import fcntl
import os
import struct
import sys

# 本机内核（6.14）实测可用的 ioctl 号。V4L2 核心会精确校验 size 字段，
# 结构体大小对不上就直接 ENOTTY，所以这里写死验证过的值。
QUERYCTRL = 0xC0445624  # _IOWR('V', 36, struct v4l2_queryctrl) 68 字节
GCTRL = 0xC008561B      # _IOWR('V', 27, struct v4l2_control)     8 字节
SCTRL = 0xC008561C      # _IOWR('V', 28, struct v4l2_control)     8 字节
NEXT_CTRL = 0x80000000
CTRL_BASE = 0x00980001

FOCUS_ABS = 0x009a090a   # V4L2_CID_FOCUS_ABSOLUTE
FOCUS_AUTO = 0x009a090c  # V4L2_CID_FOCUS_AUTO
FLAG_INACTIVE = 0x0010

USAGE = __doc__.split('用法:')[1].split('注意')[0].rstrip()


def die(msg):
    sys.stderr.write('cam-focus: %s\n' % msg)
    sys.exit(1)


def query(fd, cid):
    buf = bytearray(68)
    struct.pack_into('<I', buf, 0, cid)
    fcntl.ioctl(fd, QUERYCTRL, buf, True)
    cid, ctype = struct.unpack_from('<II', buf, 0)
    name = bytes(buf[8:40]).split(b'\0')[0].decode(errors='replace')
    mn, mx, step, dflt, flags = struct.unpack_from('<IIIII', buf, 40)
    return dict(id=cid, type=ctype, name=name, min=mn, max=mx,
                step=step, default=dflt, flags=flags)


def get(fd, cid):
    buf = bytearray(8)
    struct.pack_into('<I', buf, 0, cid)
    fcntl.ioctl(fd, GCTRL, buf, True)
    return struct.unpack_from('<i', buf, 4)[0]


def put(fd, cid, val):
    buf = bytearray(8)
    struct.pack_into('<Ii', buf, 0, cid, val)
    fcntl.ioctl(fd, SCTRL, buf, True)


def all_controls(fd):
    out, cid = [], CTRL_BASE | NEXT_CTRL
    while True:
        try:
            c = query(fd, cid)
        except OSError:
            break
        out.append(c)
        cid = c['id'] | NEXT_CTRL
    return out


def find(ctrls, cid):
    for c in ctrls:
        if c['id'] == cid:
            return c
    return None


def cmd_list(fd):
    ctrls = all_controls(fd)
    if not ctrls:
        die('读不到任何控件（换设备试试？）')
    width = max(len(c['name']) for c in ctrls)
    for c in ctrls:
        try:
            cur = get(fd, c['id'])
        except OSError:
            cur = None
        marks = []
        if c['flags'] & FLAG_INACTIVE:
            marks.append('inactive')
        if c['id'] == FOCUS_AUTO:
            marks.append('← 用它开关自动对焦')
        elif c['id'] == FOCUS_ABS:
            marks.append('← 自动对焦关掉后由它设焦点')
        rng = '' if c['type'] == 2 else ' [%s..%s/%s]' % (c['min'], c['max'], c['step'])
        print('  %#010x  %-*s = %-8s%s %s' % (
            c['id'], width, c['name'], cur, rng, ' '.join(marks)))


def cmd_lock(fd, value):
    if find(all_controls(fd), FOCUS_AUTO) is None:
        die('这台设备没有暴露自动对焦控件（AF 不走 UVC，Linux 侧没法控制）')
    put(fd, FOCUS_AUTO, 0)
    print('自动对焦: 关（镜头就冻结在当前位置）')
    if value is not None:
        try:
            put(fd, FOCUS_ABS, int(value))
        except OSError as e:
            die('设焦点值失败: %s' % e)
        print('焦点值  : %s' % get(fd, FOCUS_ABS))
    else:
        c = find(all_controls(fd), FOCUS_ABS)
        if c:
            print('焦点值  : %s（范围 %s..%s，步进 %s）' % (
                get(fd, FOCUS_ABS), c['min'], c['max'], c['step']))


def cmd_auto(fd):
    if find(all_controls(fd), FOCUS_AUTO) is None:
        die('这台设备没有暴露自动对焦控件')
    put(fd, FOCUS_AUTO, 1)
    print('自动对焦: 开')


def main(argv):
    dev, mode, value = '/dev/video0', 'list', None
    rest = []
    i = 0
    while i < len(argv):
        if argv[i] == '-d' and i + 1 < len(argv):
            dev = argv[i + 1]
            i += 2
            continue
        if argv[i] in ('-h', '--help'):
            print(USAGE)
            return 0
        rest.append(argv[i])
        i += 1
    if rest:
        mode = rest[0]
    if len(rest) > 1:
        value = rest[1]
    if mode not in ('list', 'lock', 'auto'):
        die('不认识的子命令 %r\n%s' % (mode, USAGE))

    try:
        fd = os.open(dev, os.O_RDWR | os.O_NONBLOCK)
    except OSError as e:
        die('打不开 %s: %s' % (dev, e))
    try:
        print('%s:' % dev)
        if mode == 'list':
            cmd_list(fd)
        elif mode == 'lock':
            cmd_lock(fd, value)
        else:
            cmd_auto(fd)
    finally:
        os.close(fd)
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
